properties.query:
let windowSize = 1h;

// S23: GNSS/RF Jamming
let S23 =
    UAVDatalinkConn_CL
    | where TimeGenerated > ago(windowSize)
    | where ConnEvent == 'signal_jam' or RssiDrop_dB > 15
    | extend Stage = 'S23', UAVId = tostring(UAVId)
    | where isnotempty(UAVId)
    | project TimeGenerated, Stage, UAVId;

// S109: Navigation Reject/Mission Fail
let S109 =
    UAVMission_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType in ('nav_reject','mission_fail')
    | extend Stage = 'S109', UAVId = tostring(UAVId)
    | where isnotempty(UAVId)
    | project TimeGenerated, Stage, UAVId;

// S5: AOI Excursion/Mission Fail
let S5 =
    UAVAlarm_CL
    | where TimeGenerated > ago(windowSize)
    | where AlarmType in ('AOI_BREACH','MISSION_ABORT','NAV_FAIL')
    | extend Stage = 'S5', UAVId = tostring(UAVId)
    | where isnotempty(UAVId)
    | project TimeGenerated, Stage, UAVId;

union S23, S109, S5
| summarize StagesSeen = make_set(Stage), StageCount = dcount(Stage), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated) by UAVId
| where StageCount >= 2
| extend CampaignType = "C8_GNSS재밍_항법거부_AOI이탈"
| extend StepSummary = strcat("Stages=", tostring(StagesSeen), " | First=", tostring(FirstSeen), " | Last=", tostring(LastSeen))
| extend Severity = "High"
| project FirstSeen, LastSeen, UAVId, StagesSeen, StageCount, CampaignType, StepSummary, Severity
